 if(error)return out({error:"تعذر تحميل المشاركين."},500);
 return out({ok:true,enrollments:(data||[]).map((x:any)=>({student_id:x.student_id,course_key:x.course_key,course_title:x.course_title,telegram_group_url:x.telegram_group_url,full_name:x.students?.full_name||"",level:x.students?.level||"",study_mode:x.students?.study_mode||""}))});
