if(action==="course_enroll_students"){
 if(!await isTeacher(req))return out({error:"سجلي الدخول كأستاذة أولًا."},401);
 const key=String(b.course_key||""),title=String(b.course_title||"").trim(),ids=Array.isArray(b.student_ids)?[...new Set(b.student_ids.map((x:any)=>String(x).trim()).filter(Boolean))]:[],url=String(b.telegram_group_url||"").trim();
 if(!key.includes("|")||!title||!ids.length||ids.length>300)return out({error:"تحققي من الدورة والتلاميذ المحددين."},400);
 if(url&&(!/^https:\/\//i.test(url)||url.length>1000))return out({error:"رابط تيليغرام غير صحيح."},400);
 const level=key.split("|")[0];
 const {data:students,error:se}=await db.from("students").select("id,level,status").in("id",ids);
 if(se||!students||students.length!==ids.length||students.some((s:any)=>s.level!==level||s.status!=="active"))return out({error:"توجد أسماء غير نشطة أو لا تنتمي إلى المستوى المحدد؛ لم يتم الحفظ."},400);
 const rows=ids.map((student_id:string)=>({student_id,course_key:key,course_title:title,telegram_group_url:url||null,is_active:true,updated_at:new Date().toISOString()}));
 const {error}=await db.from("student_course_enrollments").upsert(rows,{onConflict:"student_id,course_key"});
 if(error){console.error("course_enroll_students upsert failed",{message:error.message,code:error.code,details:error.details,hint:error.hint,course_key:key,student_count:ids.length});return out({error:"تعذر حفظ المشاركين: "+(error.message||"خطأ في قاعدة البيانات"),code:error.code||null,details:error.details||null,hint:error.hint||null},500);}
 return out({ok:true,saved:rows.length});
}
