if(action==="course_save_resource"){
 if(!await isTeacher(req))return out({error:"سجلي الدخول كأستاذة أولًا."},401);
 const id=String(b.id||"").trim(),key=String(b.course_key||""),title=String(b.title||"").trim(),type=String(b.resource_type||""),url=String(b.resource_url||"").trim(),description=String(b.description||"").trim(),published=b.is_published===true;
 if(!key.includes("|")||key.length>250||!title||title.length>200||!["summary","exercise","solution","lesson","video","link"].includes(type)||!/^https:\/\//i.test(url)||url.length>2048||description.length>2000)return out({error:"تحققي من عنوان المورد ونوعه ورابطه."},400);
 const values={course_key:key,title,resource_type:type,resource_url:url,description,is_published:published,updated_at:new Date().toISOString()};
 if(id){const {data,error}=await db.from("review_course_resources").update(values).eq("id",id).select("id").maybeSingle();if(error||!data)return out({error:"تعذر تعديل المورد."},400);return out({ok:true,id});}
 const {data,error}=await db.from("review_course_resources").insert(values).select("id").single();if(error||!data)return out({error:"تعذر حفظ المورد."},400);return out({ok:true,id:data.id});
}
